import tensorflow as tf

@tf.function
def serve(x):
    return model(x)

tf.saved_model.save(model, 'serving/1', signatures={'serving': serve})

class MyLayer(tf.keras.layers.Layer):
    def __init__(self, units):
        super().__init__()
        self.units = units
    def call(self, inputs):
        w = tf.Variable(tf.random.normal((inputs.shape[-1], self.units)))
        return tf.matmul(inputs, w)
